import json, time, urllib.request, urllib.error
from datetime import datetime, timezone

BASE = 'http://localhost:8080'
token = None
customer_cache = {}

def request(path, authenticated=True):
    global token
    attempts = 0
    while True:
        attempts += 1
        if authenticated and token is None:
            token = [REDACTED_SECRET]'/token', False)['token']
        req = urllib.request.Request(BASE + path)
        if authenticated:
            req.add_header('Authorization', 'Bearer ' + token)
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                return json.load(resp)
        except urllib.error.HTTPError as exc:
            if exc.code == 401 and authenticated:
                token = None
                continue
            if exc.code == 429:
                retry = exc.headers.get('Retry-After', '1')
                try:
                    delay = float(retry)
                except ValueError:
                    delay = 1.0
                time.sleep(max(delay, 0))
                continue
            if 500 <= exc.code < 600 and attempts < 20:
                time.sleep(min(attempts, 5))
                continue
            raise
        except (urllib.error.URLError, TimeoutError):
            if attempts >= 20:
                raise
            time.sleep(min(attempts, 5))

def customer(cid):
    if cid not in customer_cache:
        customer_cache[cid] = request('/customers/' + str(cid))
    return customer_cache[cid]

start = datetime(2025, 3, 1, tzinfo=timezone.utc)
end = datetime(2025, 6, 1, tzinfo=timezone.utc)
seen = set()
duplicates = 0
qualifying = []
page = 1
pages_seen = set()
while True:
    if page in pages_seen:
        raise RuntimeError(f'pagination loop at page {page}')
    pages_seen.add(page)
    data = request('/orders?page=' + str(page))
    if data['page'] "'!= page:
        raise RuntimeError(f'"'requested page {page}, got {data[\"page\"]}')
    for order in data['items']:
        oid = order['id']
        if oid in seen:
            duplicates += 1
            continue
        seen.add(oid)
        placed = datetime.fromisoformat(order['placed_at'].replace('Z', '+00:00')).astimezone(timezone.utc)
        if order['status'] == 'shipped' and start <= placed < end:
            qualifying.append(order)
    if data['next'] is None:
        total_pages = data['total_pages']
        if page "'!= total_pages:
            raise RuntimeError(f'"'ended at page {page}, total_pages={total_pages}')
        break
    page += 1

regions = {'north': 0, 'south': 0, 'east': 0, 'west': 0}
for order in qualifying:
    cust = customer(order['customer_id'])
    numerator = order['amount_cents'] * (100 - cust['discount_pct'])
    discounted = (numerator + 50) // 100
    regions[cust['region']] += discounted

result = {
    'total_cents': sum(regions.values()),
    'order_count': len(qualifying),
    'duplicates_skipped': duplicates,
    'by_region': regions,
}
print(json.dumps(result, indent=2))
print(json.dumps({'pages': len(pages_seen), 'unique_listings': len(seen), 'customers_fetched': len(customer_cache)}, sort_keys=True))
